BOOL __fastcall InitPerspective(D2GfxSettingsStrc * pSettings, ::D2GfxHelperStrc * pHelpers) {
    DWORD DVar1;
    uint8_t ddDeviceIdentifier[2128];
    IDirectDraw1* lpDD = 0;
    if (g_bD3DCoreInitialized) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x687);
      exit(-1);
    }
    if (gnD3DTextureCapFlags & Fog::BitBuffer::gadwBitMasks[0]) {
      pD2GFXRenderedDataStrc = pSettings;
      D2GfxRendereInitFunctionsStrc = pHelpers;
      DVar1 = DirectDrawCreate(0, &lpDD, nullptr);
    } else {
      pD2GFXRenderedDataStrc = pSettings;
      D2GfxRendereInitFunctionsStrc = pHelpers;
      DVar1 = DirectDrawCreate(&gsD3DAdapterGuid, &lpDD, nullptr);
    }
    if (DVar1) {
      DIRECTD3D_LogError("DirectDrawCreate failed!", DVar1);
      return 0;
    }

    DVar1 = lpDD->lpVtbl->QueryInterface((IDirectDraw*)lpDD, (IID*)&IID_IDirectDraw7, (LPVOID*)&g_pDirectDraw7);
    if (DVar1) {
      DIRECTD3D_LogError("Failed to get DirectDraw4 interface!", DVar1);
      return 0;
    }

    lpDD->lpVtbl->Release((IDirectDraw*)lpDD);
    lpDD = 0;
    DVar1 = g_pDirectDraw7->lpVtbl->QueryInterface(g_pDirectDraw7, (IID*)&D3DGuid, (LPVOID*)&g_pDirect3D7);
    if (DVar1) {
      DIRECTD3D_LogError("Failed to get D3D interface!", DVar1);
      return 0;
    }

    DVar1 = g_pDirectDraw7->lpVtbl->GetDeviceIdentifier(g_pDirectDraw7, ddDeviceIdentifier, 0);
    if (DVar1) {
      DIRECTD3D_LogError("Failed to get device identifier interface!", DVar1);
    }

    atexit((void (__cdecl *)())(BOOL (*)())Renderer::thunk_Release);
    g_bD3DCoreInitialized = 1;
    RENDERER_D3D_InitLightingTable();
    RENDERER_D3D_InitPerspectiveTransformTable();
    RENDERER_D3D_InitPerspectiveVertexBuffer();
    RENDERER_D3D_InitSmackerVertexBuffer();
    RENDERER_SelectedRendererCore = D2_NEW_AT(D2RendererCoreStrc, ".\\Src\\d3dCore.cpp", 0x6ea);
    /* LPCRITICAL_SECTION lpCriticalSection for InitializeCriticalSection */ InitializeCriticalSection(&RENDERER_SelectedRendererCore->sLock);
    return 1;
}

